<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue'; import { HostSurface } from '../../platform/host-adapter.mjs'; import { createReportsApi, dateRange } from './domain/reports-api.mjs'; import { reportsOverviewViewModel } from './domain/reports-view.mjs'; import ReportsOverviewDesktop from './desktop/ReportsOverviewDesktop.vue'; import ReportsOverviewMobile from './mobile/ReportsOverviewMobile.vue';
const props=defineProps({surface:String,adapter:Object,hostUnavailable:Boolean});const emit=defineEmits(['back']);const api=createReportsApi();const isNative=computed(()=>props.surface===HostSurface.NATIVE);const safeArea=ref(props.adapter?.getSafeArea?.()||{});const safeAreaStyle=computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap((side)=>Number.isFinite(Number(safeArea.value?.[side]))?[[`--mds-mobile-safe-${side}`,`${Number(safeArea.value[side])}px`]]:[])));const state=reactive({phase:'loading',range:{...dateRange('month'),kind:'month'},overview:null,error:null});
async function load(kind=state.range.kind){if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.'};return;}state.range={...dateRange(kind),kind};state.phase='loading';state.error=null;try{state.overview=reportsOverviewViewModel(await api.getOverview(state.range));state.phase='ready';}catch(error){state.phase='error';state.error=error;}}function back(){if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'reports-overview'});emit('back');}onMounted(load);
</script>
<template><div v-if="state.phase==='loading'" :class="isNative?'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]':'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28"/></div><section v-else-if="state.phase==='error'" :class="isNative?'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]':'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Báo cáo" @back="back"/><MEmptyState :title="state.error.status===403?'Bạn không có quyền xem báo cáo':'Không thể mở báo cáo'" :description="state.error.message"/></section><ReportsOverviewMobile v-else-if="isNative" :overview="state.overview" :range="state.range" :loading="state.phase==='loading'" :safe-area-style="safeAreaStyle" @back="back" @range="load"/><ReportsOverviewDesktop v-else :overview="state.overview" :range="state.range" :loading="state.phase==='loading'" @range="load"/></template>
